/**
 * مولّدات مسائل كاملة (سؤال + جواب نهائي + طريقة بخطوات + أخطاء شائعة) لكل درس.
 * الإجابات محسوبة يدوياً ومتحقّق منها — تُربط بالدرس عبر مفتاح `${grade}|${topic}|${lessonOrder}`.
 * تُضاف الدفعات تدريجياً (صفّاً صفّاً). الدروس غير المغطّاة تستخدم نصوص الخطة المؤقتة.
 */
import { Difficulty } from '@prisma/client';
import type { FigureSpec } from '@khatwa/shared';

export type GenStep = { description: string; expression: string; hint: string };
export type GenMistake = { description: string; wrongExample: string; correction: string };
export type GenProblem = {
  question: string;
  finalAnswer: string;
  difficulty: Difficulty;
  method: { name: string; steps: GenStep[] };
  commonMistakes: GenMistake[];
  figure?: FigureSpec; // مخطط هندسي اختياري يُعرض مع السؤال
};
export type LessonGen = () => GenProblem[];

const E = Difficulty.easy;
const M = Difficulty.medium;
const H = Difficulty.hard;

const st = (description: string, expression: string, hint: string): GenStep => ({ description, expression, hint });
const mk = (
  question: string,
  finalAnswer: string,
  difficulty: Difficulty,
  methodName: string,
  steps: GenStep[],
  mistakes: GenMistake[] = [],
  figure?: FigureSpec,
): GenProblem => ({ question, finalAnswer, difficulty, method: { name: methodName, steps }, commonMistakes: mistakes, figure });

